// Fixed application with security improvements

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Body parsing with size limits to prevent abuse
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Middleware to simulate authentication check
const authenticate = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  // In production, validate against a secure store or use JWT
  if (apiKey === process.env.API_KEY) {
    return next();
  }
  res.status(401).json({ error: 'Unauthorized' });
};

app.get('/health', authenticate, (req, res) => {
  // Removed timestamp to reduce information exposure
  res.json({ status: 'ok' });
});

app.get('/users', authenticate, (req, res) => {
  // Validating query parameters as example
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In production, fetch from DB with proper access control
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// Example POST endpoint with input validation
app.post('/user', authenticate, [
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process valid input
  res.status(201).json({ message: 'User created' });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

// Handle 404
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Port from environment or default
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

