  // Hide Express version for security through obscurity
  hidePoweredBy: true,
  // Prevent XSS attacks
  xssFilter: true,
  // Prevent sniffing of MIME types
  noSniff: true,
  // Strict Transport Security
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

